function CandleChart({candles=[]}){const a=candles.slice(-60);if(!a.length)return <p>No candle data</p>;const hi=Math.max(...a.map(c=>c[2])),lo=Math.min(...a.map(c=>c[3])),span=hi-lo||1;const y=v=>20+(hi-v)/span*190;const w=680/a.length;return <svg viewBox="0 0 760 245" role="img" aria-label="Five-minute OHLC candle chart" style={{width:'100%',maxHeight:320,display:'block'}}>{[0,1,2,3,4].map(i=><g key={i}><line x1="0" x2="690" y1={20+i*47.5} y2={20+i*47.5} stroke="#e2e8f0"/><text x="700" y={24+i*47.5} fontSize="11" fill="#334155">{fmt(hi-i*span/4,0)}</text></g>)}{a.map((c,i)=>{const x=8+w*i+w/2,col=c[4]>=c[1]?'#15803d':'#dc2626';return <g key={c[0]}><line x1={x} x2={x} y1={y(c[2])} y2={y(c[3])} stroke={col}/><rect x={x-w*.32} y={Math.min(y(c[1]),y(c[4]))} width={Math.max(1,w*.64)} height={Math.max(1,Math.abs(y(c[1])-y(c[4])))} fill={col}/>{i%Math.max(1,Math.ceil(a.length/5))===0&&<text x={x} y="231" fontSize="10" fill="#475569">{new Date(c[0]).toLocaleTimeString('en-GB',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit'})}</text>}</g>})}</svg>}
