const pnlColor=v=>v==null||v===0?'#475569':v>0?'#166534':'#b91c1c';
const pnlBg=v=>v==null||v===0?'#f8fafc':v>0?'#dcfce7':'#fee2e2';
const signed=v=>v==null?'—':(v>0?'+':v<0?'−':'')+'₹'+fmt(Math.abs(v));
const summarize=(rs,fn)=>{const vals=rs.map(fn).filter(v=>v!=null&&Number.isFinite(v));const win=vals.filter(v=>v>0),lose=vals.filter(v=>v<0);return {n:vals.length,w:win.length,l:lose.length,flat:vals.length-win.length-lose.length,profit:vals.length?win.reduce((x,y)=>x+y,0):null,loss:vals.length?lose.reduce((x,y)=>x+y,0):null,net:vals.length?vals.reduce((x,y)=>x+y,0):null,rate:vals.length?100*win.length/vals.length:null};};
const todayRows=cohortRows.filter(r=>r.trade_day===today);
